            ["Idee per Simpler"] = "Ideas for Simpler",
            ["Pagina delle idee: «Torna alla scena» la chiude"] = "Ideas page: «Back to the scene» closes it",
            ["Scena di esempio"] = "Example scene",
            ["Tutto su Simpler, in italiano e in inglese, sul"] = "All about Simpler, in English and Italian, on the",
            ["sito ufficiale"] = "official website",
            ["Scena di esempio · Cosmetic shop"] = "Example scene · Cosmetic shop",
            ["Apre la scena di esempio. Simpler ne fa una copia nella cartella Documenti\\Simpler\\Examples: puoi modificarla e salvarla, l'originale resta com'è"] = "Opens the example scene. Simpler makes a copy of it in the Documents\\Simpler\\Examples folder: you can change and save it, the original stays as it is",
            ["Ci sono modifiche non salvate in «{0}».\nVuoi salvarle prima di aprire la scena di esempio?"] = "There are unsaved changes in «{0}».\nDo you want to save them before opening the example scene?",
            ["Non riesco a copiare la scena di esempio nei Documenti: "] = "Cannot copy the example scene into Documents: ",
            ["Non riesco a copiare la scena di esempio in {0}: "] = "Cannot copy the example scene into {0}: ",
            ["Apre la scena di esempio. Simpler ne fa una copia nella cartella «Examples», accanto alla tua libreria dei modelli (la cartella scelta all'installazione): puoi modificarla e salvarla, l'originale resta com'è"] = "Opens the example scene. Simpler makes a copy of it in the «Examples» folder, next to your library of models (the folder chosen when installing): you can change and save it, the original stays as it is",
            ["Aggiornamenti"] = "Updates",
            ["Controlla automaticamente gli aggiornamenti"] = "Check for updates automatically",
            ["All'avvio, al massimo una volta al giorno, Simpler chiede al sito se c'è una versione nuova. Non scarica e non installa nulla da solo"] = "At start, at most once a day, Simpler asks the website whether there is a new version. It does not download or install anything by itself",
            ["Simpler invia al sito soltanto il numero di versione e la lingua. Si può disattivare."] = "Simpler sends the website only the version number and the language. It can be switched off.",
            ["Controlla ora"] = "Check now",
            ["Chiede subito al sito se c'è una versione nuova di Simpler"] = "Asks the website now whether there is a new version of Simpler",
            ["Controllo in corso…"] = "Checking…",
            ["Non è stato possibile controllare: il sito non risponde o manca la connessione. Riprova più tardi."] = "It was not possible to check: the website does not answer or there is no connection. Try again later.",
            ["Questa versione non è più aggiornata: è disponibile Simpler {0}."] = "This version is no longer up to date: Simpler {0} is available.",
            ["È disponibile Simpler {0}."] = "Simpler {0} is available.",
            ["La trovi nella striscia in basso nella finestra di Simpler."] = "You find it in the strip at the bottom of the Simpler window.",
            ["Hai già l'ultima versione (Simpler {0})."] = "You already have the latest version (Simpler {0}).",
            ["Salta questa versione"] = "Skip this version",
            ["Non avvisare più per Simpler {0}: si avviserà per la versione successiva"] = "Do not notify again for Simpler {0}: the next version will be notified",
            ["Più tardi"] = "Later",
            ["Nascondi fino al prossimo avvio di Simpler"] = "Hide until the next start of Simpler",
            ["Scarica"] = "Download",
            ["Apre nel browser la pagina per scaricare la nuova versione: Simpler non scarica né installa nulla da solo"] = "Opens in the browser the page to download the new version: Simpler does not download or install anything by itself",
            ["Apre nel browser le novità della nuova versione"] = "Opens in the browser what's new in the new version",
            ["Questa versione di Simpler non è più aggiornata: scarica Simpler {0}"] = "This version of Simpler is no longer up to date: download Simpler {0}",
            ["Disponibile Simpler {0}"] = "Simpler {0} available",
            ["Materiali del terreno…"] = "Terrain materials…",
            ["applico i materiali"] = "putting on the materials",
            ["scarico le texture {0}%"] = "downloading the textures {0}%",
            ["Esc: continua senza aspettare"] = "Esc: go on without waiting",
            ["I materiali del terreno arriveranno da soli appena scaricate le texture (un materiale scelto nel frattempo resta)"] = "The terrain materials will come by themselves once the textures are downloaded (a material chosen meanwhile stays)",
            ["Roccia scolpita"] = "Sculpted rock",
            ["Pareti a cenge e salti, canaloni, creste frastagliate sui pendii ripidi: 0% = forme morbide e consumate"] = "Walls of ledges and drops, gullies, jagged crests on the steep slopes: 0% = soft, worn shapes",
            ["Spigolosità"] = "Sharpness",
            ["Creste e canaloni più netti, roccia più rotta"] = "Sharper crests and gullies, more broken rock",
            ["Quanto le pareti sono fatte a cenge e salti, come strati di roccia"] = "How much the walls are made of ledges and drops, like layers of rock",
            ["Strati di roccia"] = "Rock layers",
            ["Spessore degli strati"] = "Layer thickness",
            ["Altezza di un salto di roccia (di partenza: dal dislivello del terreno)"] = "Height of one rock step (at first: from the relief of the terrain)",
            ["Inclinazione degli strati"] = "Layer tilt",
            ["Gli strati di roccia non sono orizzontali: quanto pendono"] = "Rock layers are not level: how much they tilt",
            ["Fare ora il render del fotogramma «{0}» ({1}×{2}) dalla vista attuale?"] = "Render the «{0}» keyframe ({1}×{2}) from the current view now?",
            ["Il fotogramma che c'è adesso viene sostituito."] = "The keyframe there is now will be replaced.",
            ["Colori dal terreno"] = "Colours from the terrain",
            ["Scultura"] = "Sculpting",
            ["Scolpisci il terreno"] = "Sculpt the terrain",
            ["Un pennello per modellare il terreno a mano: tieni premuto il tasto sinistro sulla vista e trascina. Il terreno cambia subito nella vista; Blender lo rifà una volta sola, quando chiudi lo strumento (spegnendolo, cambiando pannello, passando al path tracing, al render finale o salvando): solo allora «Occupato · attendi». Le zone si ricalcolano con la nuova forma (dove diventa ripido roccia, dove spiani prato) e gli ecosistemi e le pietre seguono. Le pennellate restano nel progetto e valgono anche per «Un'altra versione», la dimensione e il dettaglio. Mentre scolpisci Ctrl+Z toglie l'ultima pennellata; dopo, tutta la sessione è un solo passo di Ctrl+Z. [ e ] cambiano il diametro, Esc chiude"] = "A brush to shape the terrain by hand: hold the left button on the view and drag. The terrain changes at once in the view; Blender makes it again only once, when you close the tool (switching it off, changing panel, going to path tracing, the final render or saving): only then «Busy · wait». The zones follow the new shape (rock where it gets steep, grass where you flatten) and the ecosystems and stones follow. The strokes stay in the project and also apply to «Another version», the size and the detail. While sculpting Ctrl+Z takes away the last stroke; afterwards the whole session is one Ctrl+Z step. [ and ] change the diameter, Esc closes",
            ["Alza"] = "Raise",
            ["Alza: solleva il terreno sotto il pennello, di più al centro. Più passate alzano di più. Con Maiusc premuto abbassa"] = "Raise: lifts the terrain under the brush, more at the centre. More passes raise more. With Shift held it lowers",
            ["Abbassa"] = "Lower",
            ["Abbassa: scava il terreno sotto il pennello, di più al centro. Più passate scavano di più. Con Maiusc premuto alza"] = "Lower: digs the terrain under the brush, more at the centre. More passes dig more. With Shift held it raises",
            ["Liscia: toglie gobbe e buche sotto il pennello, la pendenza resta. Utile dopo Alza e Abbassa, o per ammorbidire una cresta"] = "Smooth: takes away bumps and holes under the brush, the slope stays. Useful after Raise and Lower, or to soften a crest",
            ["Quanto è largo il pennello sul terreno ([ e ] sulla vista). Grande per modellare colline e valli, piccolo per un argine o un sentiero"] = "How wide the brush is on the terrain ([ and ] on the view). Big to shape hills and valleys, small for a bank or a path",
            ["Quanto agisce ogni passata: bassa per ritocchi graduali, alta per cambiare molto in fretta. Con Alza e Abbassa al 100% una passata sposta il centro di circa un decimo del diametro"] = "How much each pass does: low for gradual touches, high to change a lot quickly. With Raise and Lower at 100% one pass moves the centre by about a tenth of the diameter",
            ["Morbidezza del bordo"] = "Edge softness",
            ["Come finisce il pennello: 0% = tutto il cerchio agisce uguale e il bordo resta un gradino netto; 100% = agisce soprattutto al centro e sfuma verso il bordo"] = "How the brush ends: 0% = the whole circle acts the same and the edge stays a sharp step; 100% = it acts mostly at the centre and fades towards the edge",
            ["Il terreno vero si aggiorna quando chiudi lo strumento. Ctrl+Z toglie l'ultima pennellata, Maiusc inverte Alza e Abbassa."] = "The real terrain is updated when you close the tool. Ctrl+Z takes away the last stroke, Shift swaps Raise and Lower.",
            ["Pennellate nel terreno: {0}"] = "Strokes on the terrain: {0}",
            ["Togli tutte le modifiche"] = "Remove all changes",
            ["Riporta il terreno alla forma che aveva prima di tutte le pennellate di «Scultura» (Ctrl+Z la rimette)"] = "Takes the terrain back to its shape before all the «Sculpting» strokes (Ctrl+Z puts them back)",
            ["Forma e roccia"] = "Shape and rock",
            ["Zone del terreno"] = "Terrain zones",
            ["Spianata e bordi"] = "Flat area and edges",
            ["Usa i colori dal terreno"] = "Use colours from the terrain",
            ["Il colore segue la forma del terreno: creste più chiare, canaloni più scuri, colate sulle pareti, fasce degli strati di roccia, più scuro dove si raccoglie l'acqua. Cambia solo i materiali delle zone, non la forma"] = "The colour follows the shape of the land: lighter crests, darker gullies, streaks down the walls, bands of the rock layers, darker where water gathers. Only the materials of the zones change, not the shape",
            ["Strisce scure che scendono lungo le pareti ripide, come l'acqua e i minerali che colano sulla roccia. 0% = nessuna colata"] = "Dark streaks running down the steep walls, like water and minerals running over the rock. 0% = no streaks",
            ["Fasce di colore sulle pareti che seguono gli strati della roccia (con lo spessore e l'inclinazione di «Forma e roccia»). 0% = parete di un colore solo"] = "Colour bands on the walls following the rock layers (with the thickness and tilt of «Shape and rock»). 0% = a wall of one colour",
            ["Creste più chiare e consumate dal vento, canaloni più scuri dove si raccoglie il materiale. 0% = colore uguale ovunque"] = "Lighter crests worn by the wind, darker gullies where material gathers. 0% = the same colour everywhere",
            ["Più scuro dove l'acqua scorre e si raccoglie: impluvi, conche, piedi dei pendii. 0% = asciutto ovunque"] = "Darker where water runs and gathers: channels, hollows, the foot of the slopes. 0% = dry everywhere",
            ["Quanto terreno lungo i canali e ai piedi dei pendii diventa la zona di ghiaia e terra invece di prato o roccia. 0% = niente ghiaia; il terreno si ricalcola"] = "How much ground along the channels and at the foot of the slopes becomes the gravel and soil zone instead of grass or rock. 0% = no gravel; the terrain is computed again",
            ["Quanto sono frastagliati i confini tra le zone (dove finisce il prato e comincia la roccia). 0% = confini che seguono solo la forma del terreno; il terreno si ricalcola"] = "How jagged the borders between the zones are (where the grass ends and the rock begins). 0% = borders that only follow the shape of the land; the terrain is computed again",
            ["Con «Sfumatura dei bordi» acceso: quanto il confine fra due materiali si frastaglia. 0% = segue la linea fra le zone, sfumato solo dai rilievi delle texture"] = "With «Border blend» on: how jagged the border between two materials gets. 0% = it follows the line between the zones, blended only by the relief of the textures",
            ["Larghezza della fascia che raccorda la spianata al terreno intorno: poco = un gradino netto, tanto = una salita lunga e dolce"] = "Width of the band joining the flat area to the terrain around: little = a sharp step, a lot = a long gentle slope",
            ["Il bordo del terreno scende al suo punto più basso, dove sta il suolo dell'Ambiente: niente gradino. Spento: il terreno finisce di netto ai lati del quadrato"] = "The edge of the terrain goes down to its lowest point, where the Environment ground is: no step. Off: the terrain ends sharply at the sides of the square",
            ["Quanto l'acqua scava valli e canali sui pendii e deposita il materiale in basso. 0% = forme come escono dal rumore, senza valli; 200% = valli profonde e conoidi grandi. Il terreno si ricalcola"] = "How much water carves valleys and channels on the slopes and lays the material down below. 0% = shapes straight from the noise, no valleys; 200% = deep valleys and big fans. The terrain is computed again",
            ["Quanto è vecchio il terreno: più alta = creste più consumate e morbide, fondovalle più pieni e piatti; più bassa = forme giovani, aspre e incise"] = "How old the terrain is: higher = more worn, softer crests, fuller and flatter valley floors; lower = young, rough, incised shapes",
            ["Un po' di erosione dell'acqua sopra la mappa di altezze: rifinisce i pendii con canali e depositi. 0% = la mappa così com'è"] = "A little water erosion over the height map: refines the slopes with channels and deposits. 0% = the map as it is",
            ["Con «Roccia scolpita»: creste e canaloni più netti, roccia più rotta e spigolosa. 0% = spigoli smussati"] = "With «Sculpted rock»: sharper crests and gullies, more broken and angular rock. 0% = rounded edges",
            ["Con «Roccia scolpita»: quanto le pareti sono fatte a cenge e salti, come strati di roccia sovrapposti. 0% = pareti continue"] = "With «Sculpted rock»: how much the walls are made of ledges and drops, like stacked layers of rock. 0% = continuous walls",
            ["Il colore segue la forma del terreno: creste più chiare, canaloni più scuri, colate sulle pareti, fasce degli strati di roccia, più scuro dove si raccoglie l'acqua"] = "The colour follows the shape of the land: lighter crests, darker gullies, streaks down the walls, bands of the rock layers, darker where water gathers",
            ["Colate sulle pareti"] = "Streaks on the walls",
            ["Strisce scure che scendono lungo le pareti ripide"] = "Dark streaks running down the steep walls",
