            ["Non sono riuscito a importare {0}."] = "Could not import {0}.",
            ["Non trovo la cartella 'engine' di Simpler.\nReinstalla Simpler o avvialo dalla sua cartella."] = "Simpler's 'engine' folder was not found.\nReinstall Simpler or start it from its folder.",
