            ["«{0}» aggiunto ai preferiti ({1})"] = "«{0}» added to favourites ({1})",
            ["Apre la cartella della libreria dove si trova l'originale"] = "Opens the library folder where the original is",
            ["Porta all'elemento"] = "Go to the item",
            ["Togli dai preferiti"] = "Remove from favourites",
            ["Aggiungi ai preferiti"] = "Add to favourites",
            ["Preferiti"] = "Favourites",
            ["Rotazione casuale di questo modello, al posto di quella generale"] = "Random rotation of this model, instead of the general one",
            ["Ora come la Rotazione casuale generale: spostalo per dare a questo modello la sua"] = "Now as the general Random rotation: move it to give this model its own",
            ["Si aggiunge alla Rotazione generale: per esempio 90° per un modello girato diversamente dagli altri"] = "Added to the general Rotation: for example 90° for a model turned differently from the others",
            ["Scala casuale di questo modello, al posto di quella generale"] = "Random scale of this model, instead of the general one",
            ["Ora come la Scala casuale generale: spostalo per dare a questo modello la sua"] = "Now as the general Random scale: move it to give this model its own",
            ["Grandezza di questo modello rispetto alla Scala generale (100% = come la Scala generale)"] = "Size of this model against the general Scale (100% = as the general Scale)",
            ["Il banco di prova è uno per scena: eccolo"] = "There is one test plot per scene: here it is",
            ["Il banco di prova è uno per scena: ora misura {0} m, con i suoi scatter"] = "There is one test plot per scene: it now measures {0} m, with its scatters",
            ["Contiene {0} scatter del banco di prova"] = "Holds {0} scatters of the test plot",
            ["Contiene uno scatter del banco di prova"] = "Holds a scatter of the test plot",
            ["Miniatura in preparazione con il path tracer…"] = "Thumbnail being made with the path tracer…",
            ["Rifai la miniatura dal banco di prova"] = "Make the thumbnail again from the test plot",
            ["Contiene {0} ecosistemi"] = "Holds {0} ecosystems",
            ["Contiene un ecosistema"] = "Holds an ecosystem",
            ["L'ecosistema metterà circa {0} pezzi su questa superficie, circa {1} GB di memoria (liberi ora: {2} GB): ci vorrà un po' e la scena peserà di più. Continuo?"] = "The ecosystem will place about {0} pieces on this surface, about {1} GB of memory (free now: {2} GB): it will take a while and the scene will be heavier. Continue?",
            ["Ecosistemi"] = "Ecosystems",
            ["Ecosistemi: vegetazione composta una volta sul banco di prova e messa su qualunque superficie"] = "Ecosystems: vegetation composed once on the test plot and put on any surface",
            ["Scatter (B): dipingi modelli della libreria sulle superfici (erba, fiori, sassi, alberi), riempi un'area o mettili in fila"] = "Scatter (B): paint library models on surfaces (grass, flowers, stones, trees), fill an area or line them up",
            ["Gli ecosistemi di Simpler: trascina su un oggetto (o sul suo materiale) e si popola · clic: sull'oggetto selezionato"] = "The Simpler ecosystems: drag onto an object (or its material) and it gets populated · click: on the selected object",
            ["Ecosistemi Simpler"] = "Simpler ecosystems",
            ["Trascina un ecosistema su un oggetto (o sul suo materiale) e si popola · clic: sull'oggetto selezionato · + per crearne uno sul banco di prova"] = "Drag an ecosystem onto an object (or its material) and it gets populated · click: on the selected object · + to create one on the test plot",
            ["Nuovo ecosistema"] = "New ecosystem",
            ["Crea un ecosistema sul banco di prova: un terreno di 20 m accanto alla scena dove dipingi e riempi aree con Scatter"] = "Create an ecosystem on the test plot: a 20 m ground next to the scene where you paint and fill areas with Scatter",
            ["{0} strati · {1} pezzi sul campione di {2} m"] = "{0} layers · {1} pieces on the {2} m sample",
            ["Trascina l'ecosistema su un oggetto della vista, o seleziona prima l'oggetto"] = "Drag the ecosystem onto an object in the view, or select the object first",
            ["Nome dell'ecosistema"] = "Name of the ecosystem",
            ["Eliminare l'ecosistema \"{0}\"? Quelli già messi nelle scene restano."] = "Delete the ecosystem \"{0}\"? The ones already placed in scenes stay.",
            ["Lascia l'ecosistema sopra un oggetto"] = "Drop the ecosystem on an object",
            ["L'ecosistema metterà circa {0} pezzi su questa superficie: ci vorrà un po' e la scena peserà di più. Continuo?"] = "The ecosystem will place about {0} pieces on this surface: it will take a while and the scene will be heavier. Go on?",
            ["Ecosistema «{0}»: circa {1} pezzi…"] = "Ecosystem «{0}»: about {1} pieces…",
            ["Ecosistema «{0}»: {1} pezzi"] = "Ecosystem «{0}»: {1} pieces",
            ["Banco di prova pronto: scegli i modelli e dipingi o riempi un'area su di lui, poi Ecosistemi ▸ Salva ecosistema"] = "Test plot ready: choose the models and paint or fill an area on it, then Ecosystems ▸ Save ecosystem",
            ["Prima crea il banco di prova (o seleziona le distribuzioni da salvare)"] = "First create the test plot (or select the distributions to save)",
            ["Salva ecosistema"] = "Save ecosystem",
            ["Ecosistema {0}"] = "Ecosystem {0}",
            ["Salvataggio dell'ecosistema e miniatura…"] = "Saving the ecosystem and its thumbnail…",
            ["Ecosistema salvato: {0} ({1} pezzi in {2} strati)"] = "Ecosystem saved: {0} ({1} pieces in {2} layers)",
            ["Ecosistema"] = "Ecosystem",
            ["Su {0}"] = "On {0}",
            ["solo il materiale «{0}»"] = "only the material «{0}»",
            ["{0} pezzi"] = "{0} pieces",
            ["Quanti pezzi del campione restano: 100% = come l'hai composto"] = "How many pieces of the sample stay: 100% = as you composed it",
            ["Più grandi o più piccoli tutti insieme"] = "Larger or smaller all together",
            ["Altra disposizione"] = "Another arrangement",
            ["Gira le tessere"] = "Turn the tiles",
            ["Il campione si ripete a tessere: ognuna girata di un quarto a caso, così la ripetizione non si vede"] = "The sample repeats in tiles: each one turned a quarter at random, so the repetition does not show",
            ["Segui la pendenza"] = "Follow the slope",
            ["I pezzi si piegano come la superficie (sassi, erba). Spento: dritti verso l'alto anche in pendenza (alberi)"] = "The pieces tilt with the surface (stones, grass). Off: straight up even on slopes (trees)",
            ["Solo sul materiale «{0}»"] = "Only on the material «{0}»",
            ["Spento: su tutto l'oggetto"] = "Off: on the whole object",
            ["Crea un ecosistema"] = "Create an ecosystem",
            ["1. Crea il banco di prova: un terreno accanto alla scena. 2. Con Scatter dipingi o riempi aree, uno strato alla volta (alberi, arbusti, erba). 3. Salva: ti ritrovi l'ecosistema in libreria, da trascinare su qualunque superficie."] = "1. Create the test plot: a ground next to the scene. 2. With Scatter paint or fill areas, one layer at a time (trees, shrubs, grass). 3. Save: the ecosystem is in the library, ready to drag onto any surface.",
            ["Dipingi o riempi aree sul banco di prova con Scatter, uno strato alla volta. Quando ti piace, salva: l'inquadratura di adesso diventa la miniatura."] = "Paint or fill areas on the test plot with Scatter, one layer at a time. When you like it, save: the current framing becomes the thumbnail.",
            ["Banco di prova 20 m"] = "Test plot 20 m",
            ["Banco di prova 50 m (boschi)"] = "Test plot 50 m (woods)",
            ["Anche delle distribuzioni già fatte nella scena possono diventare un ecosistema: selezionale nell'albero e salva."] = "Distributions already made in the scene can become an ecosystem too: select them in the tree and save.",
            ["Salva le distribuzioni selezionate"] = "Save the selected distributions",
            ["Scatter"] = "Scatter",
            ["Perché esiste Simpler"] = "Why Simpler exists",
            ["Blender, ma più semplice"] = "Blender, but simpler",
            ["Simpler nasce dalla passione per le immagini, non da un'azienda: la potenza di Blender e Cycles con un'interfaccia semplice e immediata, ispirata ai migliori programmi di visualizzazione in tempo reale. Gratuito, senza abbonamenti né registrazione."] = "Simpler was born from a passion for images, not from a company: the power of Blender and Cycles with a simple, immediate interface inspired by the best real-time visualisation software. Free, with no subscription and no registration.",
            ["Tutte le informazioni, in italiano e in inglese:"] = "Everything about Simpler, in English and Italian:",
            ["La storia"] = "The story",
            ["Perché esiste Simpler · scegli un menu qui accanto per modelli, materiali, decal, cielo e luci"] = "Why Simpler exists · pick a menu here next to it for models, materials, decals, sky and lights",
            ["Perché Simpler"] = "Why Simpler",
            ["Simpler nasce dalla passione di chi crea immagini, non da un'azienda. Uso Twinmotion da anni, per lavoro e per piacere: modero il gruppo Facebook ufficiale, ci ho scritto due libri e lo provo in anteprima come beta tester. Cercando un fotorealismo sempre più alto, ho trovato in Blender un motore straordinario, completo e libero, ma anche così complesso che persino un risultato semplice richiede tempo."] = "Simpler was born from the passion of someone who makes images, not from a company. I have used Twinmotion for years, for work and for pleasure: I moderate its official Facebook group, I have written two books about it and I test it in preview as a beta tester. Looking for ever higher photorealism, I found in Blender an extraordinary engine, complete and free, but so complex that even a simple result takes time.",
            ["Da qui l'idea: "] = "Hence the idea: ",
            ["Blender, ma più semplice."] = "Blender, but simpler.",
            ["Un'app veloce da usare come Twinmotion o D5, con dentro tutto il motore di Blender e Cycles, senza compromessi sulla qualità."] = "An app as quick to use as Twinmotion or D5, with the whole Blender and Cycles engine inside, with no compromise on quality.",
            ["Simpler è gratuito, senza abbonamenti e senza registrazione. Le immagini di qualità non dovrebbero dipendere da un canone mensile, e Simpler continua lo spirito di condivisione della comunità di Twinmotion, sulle spalle di Blender e delle texture libere di Poly Haven. Non ci sono investitori: si aggiunge una funzione solo se migliora l'immagine."] = "Simpler is free, with no subscriptions and no registration. Quality images should not depend on a monthly fee, and Simpler carries on the sharing spirit of the Twinmotion community, standing on the shoulders of Blender and of Poly Haven's free textures. There are no investors: a feature is added only if it makes the image better.",
            ["Lo sviluppo con Claude ha fatto il resto, come un intero team di sviluppo: io decido priorità e requisiti, e provo ogni versione sul mio PC."] = "Developing with Claude did the rest, like a whole development team: I set the priorities and the requirements, and I test every version on my own PC.",
            ["Tutte le informazioni su Simpler, in italiano e in inglese:"] = "Everything about Simpler, in English and Italian:",
            ["Il cielo vero (NASA): le stelle dove sarebbero a quell'ora, in quel luogo e in quel giorno, con la Via Lattea. Si vedono quando il sole è sotto l'orizzonte"] = "The real sky (NASA): the stars where they would be at that hour, place and day, with the Milky Way. They show when the sun is below the horizon",
            ["Luce della luna"] = "Moonlight",
            ["La luce fredda e debole che la luna dà alla scena (segue anche la fase: un quarto illumina circa un decimo della luna piena)"] = "The cold, weak light the moon gives the scene (it follows the phase too: a quarter gives about a tenth of the full moon)",
            ["Fase"] = "Phase",
            ["0 = luna nuova · 25 = primo quarto · 50 = luna piena · 75 = ultimo quarto"] = "0 = new moon · 25 = first quarter · 50 = full moon · 75 = last quarter",
            ["Dimensione della luna"] = "Moon size",
            ["1 = la misura vera nel cielo (mezzo grado): più grande per un effetto da cinema. La luce sulla scena non cambia"] = "1 = its real size in the sky (half a degree): larger for a cinema look. The light on the scene does not change",
            ["Sto scaricando le stelle e la luna della NASA (circa 35 MB, una volta sola)…"] = "Downloading NASA's stars and moon (about 35 MB, only once)…",
            ["Non riesco a scaricare le stelle e la luna: "] = "Cannot download the stars and the moon: ",
            ["Riprova"] = "Try again",
            ["Luminosità del disco"] = "Disc brightness",
            ["Quanto brilla il disco della luna nel cielo (non la luce sulla scena)"] = "How bright the moon's disc is in the sky (not the light on the scene)",
            ["Alone"] = "Halo",
            ["Il bagliore attorno alla luna, come attraverso l'aria"] = "The glow around the moon, as through the air",
            ["Posizione automatica"] = "Automatic position",
            ["La luna sta dalla parte opposta del sole, abbastanza alta. Spegnila per metterla dove vuoi nell'inquadratura"] = "The moon stands opposite the sun, fairly high. Turn it off to put it where you want in the frame",
            ["Quanto è alta sull'orizzonte"] = "How high above the horizon",
            ["Direzione"] = "Direction",
            ["Da dove si vede: 0° nord, 90° est, 180° sud, 270° ovest (il nord è quello del sole)"] = "Where it is seen: 0° north, 90° east, 180° south, 270° west (the north of the sun)",
            ["Luna nuova"] = "New moon",
            ["Luna crescente"] = "Waxing crescent",
            ["Primo quarto"] = "First quarter",
            ["Gibbosa crescente"] = "Waxing gibbous",
            ["Luna piena"] = "Full moon",
            ["Gibbosa calante"] = "Waning gibbous",
            ["Ultimo quarto"] = "Last quarter",
            ["Luna calante"] = "Waning crescent",
            ["Stelle e luna pronte"] = "Stars and moon ready",
            ["Centra ogni pezzo"] = "Centre every piece",
            ["Ogni parte staccata dell'oggetto (i due fanali di un'auto, le lenti di un fanale, le piastrelle separate) ha la texture centrata sul suo centro, invece di un solo centro per tutto l'oggetto. Sposta X/Y spostano allo stesso modo tutti i pezzi"] = "Every separate part of the object (the two lamps of a car, the lenses of a lamp, separate tiles) gets the texture centred on its own middle, instead of one middle for the whole object. Offset X/Y move all the pieces alike",
            ["Immagine (colore)"] = "Picture (colour)",
            ["La figura della decal: la sua trasparenza ritaglia la forma (se non c'è una mappa di opacità)"] = "The picture of the decal: its transparency cuts out the shape (when there is no opacity map)",
            ["La figura della decal. Cambiandola la misura resta: Larghezza e Altezza in Forma"] = "The picture of the decal. Changing it keeps the size: Width and Height in Shape",
            ["Rilievo (normale)"] = "Relief (normal)",
            ["Senza mappa la decal è piatta. La bacchetta la ricava dall'immagine."] = "Without a map the decal is flat. The wand makes one from the picture.",
            ["La mappa decide quanto è lucida, punto per punto."] = "The map decides how glossy it is, point by point.",
            ["La mappa decide dove è metallo, punto per punto."] = "The map decides where it is metal, point by point.",
            ["Bianco = si vede, nero = trasparente. L'Opacità in alto la attenua tutta."] = "White = visible, black = transparent. The Opacity above fades all of it.",
            ["Senza mappa conta la trasparenza dell'immagine (PNG)."] = "Without a map the picture's own transparency counts (PNG).",
            ["Emissione (luce)"] = "Emission (light)",
            ["La decal emette luce del suo colore: insegne, schermi, neon"] = "The decal gives off light of its colour: signs, screens, neon",
            ["Forma"] = "Shape",
            ["Mappe: {0} (in Avanzate)"] = "Maps: {0} (in Advanced)",
            ["rilievo"] = "relief",
            ["rugosità"] = "roughness",
            ["metallo"] = "metal",
            ["trasparenza"] = "transparency",
            ["emissione"] = "emission",
            ["Centra la mappa"] = "Centre the map",
            ["Centra sull'oggetto"] = "Centre on the object",
            ["Mette il centro della texture al centro dell'oggetto selezionato (della sua parte con questo materiale) e ce la tiene quando cambi scala o rotazione. Succede da solo quando metti una texture; spostandola a mano resta dove la metti"] = "Puts the middle of the texture on the middle of the selected object (of its part with this material) and keeps it there when you change scale or rotation. It happens by itself when you put a texture on; moved by hand, it stays where you put it",
            ["Texture centrata sull'oggetto"] = "Texture centred on the object",
            ["Orientamento"] = "Orientation",
            ["Il davanti del modello lungo l'asse rosso X (la direzione della linea dello spacing). Vale per i nuovi inserimenti e per gli scatter; le copie già nelle scene non cambiano"] = "The front of the model along the red X axis (the direction of a Spacing line). It holds for new insertions and for scatters; copies already in scenes do not change",
            ["Raddrizza"] = "Straighten",
            ["Simpler gira il modello visto dall'alto in modo che il suo lato lungo stia sull'asse rosso X"] = "Simpler turns the model, seen from above, so its long side lies on the red X axis",
            ["Gira di 90°"] = "Turn by 90°",
            ["Un quarto di giro attorno all'asse verticale"] = "A quarter turn around the vertical axis",
            ["Gira di 180°"] = "Turn by 180°",
            ["Mezzo giro: il davanti dall'altra parte"] = "Half a turn: the front the other way",
            ["{0}: orientamento in corso…"] = "{0}: turning…",
            ["{0}: nuovo orientamento salvato nella libreria"] = "{0}: new orientation saved in the library",
            ["{0}: nuovo orientamento salvato nella libreria, anche negli scatter di questo progetto"] = "{0}: new orientation saved in the library, in the scatters of this project too",
            ["Salva questo orientamento nella libreria"] = "Save this orientation to the library",
            ["Tasto destro: incolla una mappa copiata, o un'immagine dagli appunti (un ritaglio dello schermo, un'immagine copiata)"] = "Right click: paste a copied map, or an image from the clipboard (a screen cut-out, a copied image)",
            ["Incolla immagine dagli appunti"] = "Paste image from the clipboard",
            ["Negli appunti non c'è un'immagine"] = "There is no image in the clipboard",
            ["Immagine incollata come mappa: {0}"] = "Image pasted as a map: {0}",
            ["appunti"] = "clipboard",
            ["Solo questo modello"] = "Only this model",
            ["Alla prima modifica {0} riceve una copia tutta sua del materiale, su tutti i suoi pezzi che lo usano: gli altri modelli non cambiano"] = "At the first change {0} gets a copy of the material all its own, on all its pieces using it: the other models do not change",
            ["Le modifiche valgono per tutti i modelli con questo materiale"] = "The changes apply to every model with this material",
            ["Ora questo modello ha un materiale tutto suo: {0} (gli altri modelli non cambiano)"] = "Now this model has a material all its own: {0} (the other models do not change)",
            ["altri {0}"] = "{0} more",
            ["i modelli delle distribuzioni"] = "the models of distributions",
            ["Le modifiche cambiano anche: {0}"] = "The changes also change: {0}",
            ["Rotazione rispetto alla linea"] = "Rotation from the line",
            ["Rispetto alla direzione della linea, dal primo punto all'ultimo: 0° = l'asse X del modello segue la linea, 180° = senso opposto, ±90° = di traverso. Resta giusta anche nelle curve"] = "Relative to the direction of the line, from the first point to the last: 0° = the model's X axis follows the line, 180° = the opposite way, ±90° = crosswise. It stays right in the bends too",
            ["Ogni oggetto gira seguendo la direzione della linea, anche nelle curve (auto su una strada, recinzioni, panchine): la Rotazione diventa rispetto alla linea"] = "Every object turns with the direction of the line, in the bends too (cars on a road, fences, benches): the Rotation becomes relative to the line",
            ["Distanza minima tra un oggetto e il successivo lungo la linea: non si scende mai sotto, così i modelli non si sovrappongono"] = "Minimum distance between one object and the next along the line: it never goes below, so models do not overlap",
            ["A ogni intervallo si aggiunge a caso da 0 a questi metri: file meno perfette (auto parcheggiate). 0 = tutti alla stessa distanza"] = "Each gap gets a random 0 to this many metres more: less perfect rows (parked cars). 0 = all at the same distance",
            ["{0} texture di questo modello non si trovano sul disco, quindi il modello è stato salvato senza:"] = "{0} textures of this model cannot be found on disk, so the model was saved without them:",
            ["Il file è stato spostato o cancellato, oppure è su un disco non collegato. Se lo ritrovi, ricollegalo (tasto destro sul modello nell'albero ▸ Cerca texture mancanti…) e salva di nuovo il modello; altrimenti reimporta il modello dal suo file originale (FBX, OBJ…)."] = "The file was moved or deleted, or it is on a drive that is not connected. If you find it, link it again (right click on the model in the tree ▸ Find missing textures…) and save the model again; otherwise import the model again from its original file (FBX, OBJ…).",
            ["Mappe"] = "Maps",
            ["Dà rilievo alla decal (una crepa, un'incisione): cambia la luce, non la forma"] = "Gives the decal relief (a crack, an engraving): it changes the light, not the shape",
            ["Intensità normale"] = "Normal strength",
            ["Quanto si vede il rilievo della normal map (1 = com'è)"] = "How much the relief of the normal map shows (1 = as it is)",
            ["Normale DirectX"] = "DirectX normal",
            ["Accendi se il rilievo sembra rovesciato (in fuori invece che in dentro): mappe fatte per DirectX, con il verde capovolto"] = "Turn on if the relief looks reversed (raised instead of carved): maps made for DirectX, with green upside down",
            ["Chiaro = opaco, scuro = lucido (sostituisce il cursore Rugosità)"] = "Light = matte, dark = glossy (replaces the Roughness slider)",
            ["Bianco = metallo, nero = no (sostituisce il cursore Metallo)"] = "White = metal, black = not (replaces the Metal slider)",
            ["Bianco = si vede, nero = trasparente (al posto della trasparenza dell'immagine)"] = "White = visible, black = transparent (instead of the picture's transparency)",
            ["Questa decal è una macchia (scurisce la superficie sotto): non usa mappe."] = "This decal is a stain (it darkens the surface under it): it uses no maps.",
            ["Solo le parti chiare della mappa si accendono (neon, scritte luminose), del colore della decal; la forza è Luminosità"] = "Only the light parts of the map glow (neon, luminous writing), in the colour of the decal; the strength is Brightness",
            ["Genera la normale dall'immagine della decal sul tuo computer (DeepBump)"] = "Make the normal from the decal's picture on your computer (DeepBump)",
            ["Normale dall'immagine della decal"] = "Normal from the decal's picture",
            ["Contiene una decal"] = "Holds a decal",
            ["Contiene {0} decal"] = "Holds {0} decals",
            ["Sposta il pivot: il gizmo diventa viola e si sposta da solo, senza il modello; riclicca per fissarlo. Vale per tutto il modello (il padre della gerarchia)"] = "Move the pivot: the gizmo turns violet and moves alone, without the model; click again to fix it. It works on the whole model (the top of the hierarchy)",
            ["Seleziona prima il modello di cui spostare il pivot"] = "First select the model whose pivot you want to move",
            ["Sposta il gizmo viola dove vuoi il pivot del modello; riclicca il pulsante per finire"] = "Move the violet gizmo where you want the model's pivot; click the button again to finish",
            ["Pivot fissato: da ora il gizmo di questo modello sta lì"] = "Pivot fixed: from now on this model's gizmo stands there",
            ["Pivot automatico"] = "Automatic pivot",
            ["Il gizmo torna dove dicono Centro, Base o Origine"] = "The gizmo goes back to where Centre, Base or Origin say",
            ["Pivot spostato a mano"] = "Pivot moved by hand",
            ["Sposta il pivot"] = "Move the pivot",
            ["Ci sono modelli selezionati con Ctrl: un clic su un modello toglie la selezione, poi puoi inserirlo"] = "Models are selected with Ctrl: a click on a model clears the selection, then you can insert it",
            ["{0} modelli selezionati · tasto destro su uno di loro: taglia, copia, sposta, elimina · clic senza Ctrl: togli la selezione"] = "{0} models selected · right click on one of them: cut, copy, move, delete · click without Ctrl: clear the selection",
