            ["{0} modelli eliminati dalla libreria"] = "{0} models deleted from the library",
            ["Larghezza × profondità × altezza del modello, lungo i suoi assi (con la scala)"] = "Width × depth × height of the model, along its own axes (with the scale)",
            ["Accesa"] = "On",
            ["Spenta: non illumina, qualunque sia l'ora (vale più di «Dal tramonto all'alba»)"] = "Off: it gives no light, whatever the hour (it wins over «Dusk to dawn»)",
            ["Dal tramonto all'alba"] = "Dusk to dawn",
            ["Si accende da sola solo la sera e di notte, secondo l'ora dell'Ambiente: luci delle case, lampioni, insegne. Di giorno resta spenta"] = "It switches on by itself only in the evening and at night, by the hour of the Ambience: house lights, street lamps, signs. In daytime it stays off",
            ["Adesso è accesa: è sera o notte nell'Ambiente."] = "Now it is on: it is evening or night in the Ambience.",
            ["Adesso è spenta: è giorno nell'Ambiente."] = "Now it is off: it is daytime in the Ambience.",
            ["Spenta: non emette luce, qualunque sia l'ora (vale più di «Dal tramonto all'alba»); la luminanza resta impostata"] = "Off: it emits no light, whatever the hour (it wins over «Dusk to dawn»); the luminance stays set",
            ["Si accende da sola solo la sera e di notte, secondo l'ora dell'Ambiente: finestre illuminate, neon, insegne. Di giorno resta spenta"] = "It switches on by itself only in the evening and at night, by the hour of the Ambience: lit windows, neon, signs. In daytime it stays off",
