            ["Il file del contratto di licenza non è stato trovato."] = "The license agreement file was not found.",
            ["Accettato il {0} (versione {1} del contratto)"] = "Accepted on {0} (agreement version {1})",
            ["Ho letto il contratto di licenza e lo accetto."] = "I have read the license agreement and I accept it.",
            ["Ai sensi degli articoli 1341 e 1342 del Codice civile approvo specificamente le clausole 4 (nome, logo e uso corretto), 6 (contenuti di Simpler), 9 (esclusione di garanzia), 10 (limitazione di responsabilità), 11 (manleva), 12 (aggiornamenti e modifiche), 13 (risoluzione di diritto) e 15 (legge applicabile e foro competente)."] = "Under articles 1341 and 1342 of the Italian Civil Code I specifically approve clauses 4 (name, logo and fair use), 6 (Simpler content), 9 (disclaimer of warranty), 10 (limitation of liability), 11 (indemnity), 12 (updates and changes), 13 (termination by operation of law) and 15 (governing law and jurisdiction).",
            ["Non accetto"] = "I do not accept",
            ["Simpler si chiude"] = "Simpler closes",
            ["Accetto"] = "I accept",
            ["Espandi tutto l'albero"] = "Unfold the whole tree",
            ["Comprimi tutto l'albero"] = "Fold the whole tree",
            ["Sostituisci nella selezione"] = "Replace in selection",
            ["Il materiale prende il posto di quello sotto il mouse solo negli oggetti selezionati e nei loro pezzi (niente selezionato: nel modello dove lo lasci); gli altri modelli con lo stesso materiale restano com'erano"] = "The material takes the place of the one under the mouse only in the selected objects and their pieces (nothing selected: in the model where you drop it); other models with the same material stay as they were",
            ["Personalizzati"] = "Custom",
            ["{0} · CC0 (salvata nel progetto)"] = "{0} · CC0 (saved in the project)",
            ["macchia: scurisce la superficie sotto"] = "stain: darkens the surface under it",
